#include <stdio.h>
#include <stdbool.h>
#include <string.h>
#include <stdlib.h>
struct span { const char *base; size_t len; };

tests.code:
struct span s[3];
s[0].base = "hello";
s[0].len = 5;
s[1].base = "-";
s[1].len = 1;
s[2].base = "world";
s[2].len = 5;
CHECK_EQ(spans_total(s, 3), 11);
char out[16] = {0};
spans_gather(s, 3, out);
CHECK_STR_EQ(out, "hello-world");

struct span t[2];
t[0].base = NULL;
t[0].len = 3;
t[1].base = "world";
t[1].len = 5;
CHECK_EQ(spans_total(t, 2), 8);
char out2[16] = {0};
spans_gather(t, 2, out2);
CHECK_STR_EQ(out2, "world");
